import "server-only";
import { queue } from "@/lib/queue";

export async function POST(req) {
  let body;

  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const query = body?.query;

  return Response.json({ ok: true, query });
}